"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["97255"],{15235(i){i.exports=JSON.parse('{"id":"F401","slug":"ito-lemma-drift","name":"It\xf4\'s Lemma: Drift and Volatility of a Function","subject":"Quantitative Finance","section":"Quant","topic":"It\xf4\'s lemma","level":"Intermediate","aliases":["Ito formula","stochastic calculus","drift correction","change of variable"],"formula":{"latex":"df=\\\\left(f_{t}+\\\\mu S f_{S}+\\\\tfrac{1}{2}\\\\sigma^{2}S^{2}f_{SS}\\\\right)dt+\\\\sigma S f_{S}\\\\,dW","also":[],"text":"If dS = mu x S dt + sigma x S dW then a function f(S, t) has drift f_t + mu x S x f_S + 0.5 x sigma^2 x S^2 x f_SS and volatility sigma x S x f_S"},"symbols":[{"symbol":"f_t, f_S, f_SS","meaning":"First derivative in time, first and second derivative in S","unit":"number"},{"symbol":"mu","meaning":"Expected return of S","unit":"per year"},{"symbol":"sigma","meaning":"Volatility of S","unit":"per year"},{"symbol":"dW","meaning":"Random shock, normal with variance dt","unit":"number"}],"when_to_use":"Use it to find how a function of a random price behaves. The extra second-derivative term appears because squared random shocks do not average to zero: dW squared is dt. For f = ln S it shows that the log price drifts at mu minus half the variance, which explains why median growth is below mean growth.","worked_example":{"problem":"A stock at 100 has an expected return of 9% and a volatility of 25%. For f = ln S, the derivatives are f_t = 0, f_S = 1/S = 0.01 and f_SS = -1/S^2 = -0.0001. For g = S^2, they are 0, 2S = 200 and 2.","inputs":{"s":100,"mu":9,"sig":25,"ft":0,"fs":0.01,"fss":-0.0001,"gs":200,"gss":2},"steps":[{"label":"Drift of f = f_t + mu S f_S + 0.5 sigma^2 S^2 f_SS","working":"0+0.09 x 100 x 0.01+0.5 x 0.25^2 x 100^2 x -0.0001","value":"5.875%"},{"label":"Volatility of f = sigma S f_S","working":"0.25 x 100 x 0.01","value":"25.00%"},{"label":"Half the variance = 0.5 sigma^2","working":"0.5 x 0.25^2","value":"3.125%"},{"label":"Drift of S squared, divided by S squared","working":"(0.09 x 100 x 200+0.5 x 0.25^2 x 100^2 x 2) / (100^2)","value":"24.25%"}],"answer":"For ln S the drift is 5.875% per year and the volatility is 25.00%. The drift is the 9% return less half the variance (3.125%). For S squared, drift over S squared is 24.25%, which is 2 mu + sigma^2."},"calculator":{"available":true,"inputs":[{"id":"s","label":"Stock price","unit":"money","type":"number","default":100,"hint":""},{"id":"mu","label":"Expected return","unit":"%","type":"number","default":9,"hint":""},{"id":"sig","label":"Volatility","unit":"%","type":"number","default":25,"hint":""},{"id":"ft","label":"f_t (time derivative)","unit":"","type":"number","default":0,"hint":""},{"id":"fs","label":"f_S (first derivative)","unit":"","type":"number","default":0.01,"hint":""},{"id":"fss","label":"f_SS (second derivative)","unit":"","type":"number","default":-0.0001,"hint":""},{"id":"gs","label":"Second function: first derivative","unit":"","type":"number","default":200,"hint":""},{"id":"gss","label":"Second function: second derivative","unit":"","type":"number","default":2,"hint":""}],"checks":[],"steps":[{"id":"drift","label":"Drift of f = f_t + mu S f_S + 0.5 sigma^2 S^2 f_SS","expr":"ft+mu*s*fs+0.5*sig^2*s^2*fss","format":"pct3"},{"id":"vol","label":"Volatility of f = sigma S f_S","expr":"sig*s*fs","format":"pct2"},{"id":"half","label":"Half the variance = 0.5 sigma^2","expr":"0.5*sig^2","format":"pct3"},{"id":"drift2","label":"Drift of S squared, divided by S squared","expr":"(mu*s*gs+0.5*sig^2*s^2*gss)/(s^2)","format":"pct2"}],"results":["drift","vol","drift2"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"drift":0.05875,"vol":0.25,"half":0.03125,"drift2":0.2425}},"finder":{"finds":"The drift and volatility of a function of a random price","needs":"Price, return, volatility and derivatives of the function"},"related":[{"slug":"gbm-step","name":"Simulated Price Step (Monte Carlo)"},{"slug":"gbm-terminal-distribution","name":"Geometric Brownian Motion: Terminal Price Distribution"},{"slug":"brownian-motion-facts","name":"Brownian Motion Probabilities"}],"related_ids":["F055","F402","F400"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>d</mi><mi>f</mi><mo>=</mo><mrow><mo fence=\\"true\\">(</mo><msub><mi>f</mi><mi>t</mi></msub><mo>+</mo><mi>\u03BC</mi><mi>S</mi><msub><mi>f</mi><mi>S</mi></msub><mo>+</mo><mstyle displaystyle=\\"false\\" scriptlevel=\\"0\\"><mfrac><mn>1</mn><mn>2</mn></mfrac></mstyle><msup><mi>\u03C3</mi><mn>2</mn></msup><msup><mi>S</mi><mn>2</mn></msup><msub><mi>f</mi><mrow><mi>S</mi><mi>S</mi></mrow></msub><mo fence=\\"true\\">)</mo></mrow><mi>d</mi><mi>t</mi><mo>+</mo><mi>\u03C3</mi><mi>S</mi><msub><mi>f</mi><mi>S</mi></msub><mtext>\u2009</mtext><mi>d</mi><mi>W</mi></mrow><annotation encoding=\\"application/x-tex\\">df=\\\\left(f_{t}+\\\\mu S f_{S}+\\\\tfrac{1}{2}\\\\sigma^{2}S^{2}f_{SS}\\\\right)dt+\\\\sigma S f_{S}\\\\,dW</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"iqr-outlier-fences","name":"IQR Outlier Fences"},"next":{"slug":"j-curve-cumulative-cash","name":"J-Curve: Cumulative Net Cash Flow of a Fund"},"lesson":null,"total":522}')}}]);